/* ===== 智能体独立嵌入页 · Chat SDK 模式 · 窄行布局 ===== */
html,body{height:100%}
body{margin:0;display:flex;flex-direction:column;background:var(--bg)}

/* 顶部窄行品牌条 */
.ce-bar{background:rgba(250,246,239,.92);backdrop-filter:blur(12px);
  border-bottom:1px solid var(--line);flex-shrink:0}
.ce-bar .inner{max-width:var(--maxw);margin:0 auto;padding:0 24px;height:56px;
  display:flex;align-items:center;justify-content:space-between}
.ce-bar .brand{display:flex;align-items:center;gap:8px;font-weight:700;
  color:var(--ink);font-size:16px;letter-spacing:.04em;text-decoration:none}
.ce-bar .brand img{height:30px;width:auto;border-radius:6px}
.ce-bar .acts{display:flex;gap:8px;align-items:center}
.ce-back{display:inline-flex;align-items:center;gap:5px;font-size:13px;
  color:var(--gold-deep);border:1px solid var(--gold);padding:6px 14px;
  border-radius:20px;transition:.25s;background:transparent;text-decoration:none;white-space:nowrap}
.ce-back:hover{background:var(--gold);color:#fff}
.ce-member{display:inline-flex;align-items:center;gap:5px;font-size:13px;
  color:#fff;background:var(--gold-deep);padding:6px 14px;
  border-radius:20px;transition:.25s;text-decoration:none;white-space:nowrap}
.ce-member:hover{background:var(--gold)}

/* 智能体信息条 — 无边框、融合页面 */
.ce-head{background:var(--bg);
  padding:8px 24px 6px;flex-shrink:0}
.ce-head .inner{max-width:var(--maxw);margin:0 auto;
  display:flex;align-items:center;gap:12px}
.ce-badge{width:38px;height:38px;flex-shrink:0;border-radius:11px;
  display:grid;place-items:center;font-size:19px;
  background:linear-gradient(135deg,var(--gold),var(--gold-deep));
  box-shadow:0 5px 14px rgba(138,90,50,.2)}
.ce-meta{display:flex;align-items:baseline;gap:10px;min-width:0}
.ce-meta .step{font-size:12px;letter-spacing:.16em;color:var(--gold);
  white-space:nowrap;line-height:1.2;background:none;border:none;border-radius:0;
  box-shadow:none;padding:0}
.ce-meta .name{font-size:19px;font-weight:700;color:var(--gold-deep);
  line-height:1.25}

/* 非微信提示 */
.ce-tip{display:none;background:var(--gold-deep);color:#fff;font-size:12.5px;
  text-align:center;padding:7px 14px;flex-shrink:0}
.ce-tip a{color:#fff;text-decoration:underline}

/* 聊天挂载区 */
#chatMount{position:relative;flex:1;min-height:0;background:#fff;overflow:hidden}
#chatMount > *{width:100%!important;height:100%!important}
#chatMount iframe{width:100%;height:100%;border:0;display:block}

/* 加载/失败遮罩 */
.ce-loading{position:absolute;inset:0;display:flex;flex-direction:column;
  align-items:center;justify-content:center;gap:8px;background:var(--bg);
  color:var(--ink-soft);font-size:15px;text-align:center;padding:20px}
.ce-loading span{font-size:12.5px;opacity:.8;max-width:280px;line-height:1.55}

/* 微信引导卡片 */
.ce-wx-card{position:absolute;inset:0;display:flex;flex-direction:column;
  align-items:center;justify-content:center;gap:16px;background:var(--bg);
  padding:28px 20px;text-align:center;overflow-y:auto;cursor:pointer;z-index:99999}
.ce-wx-icon{font-size:48px}
.ce-wx-title{font-size:18px;font-weight:700;color:var(--gold-deep);line-height:1.3}
.ce-wx-desc{font-size:14px;color:var(--ink-soft);line-height:1.65;max-width:320px}
.ce-wx-steps{background:var(--paper);border:1px solid var(--line);
  border-radius:14px;padding:16px 18px;margin-top:4px;
  text-align:left;font-size:13px;color:var(--ink-soft);line-height:1.8;max-width:300px}
.ce-wx-steps b{color:var(--gold-deep)}
.ce-wx-btn{display:inline-flex;align-items:center;gap:6px;
  background:linear-gradient(135deg,var(--gold),var(--gold-deep));
  color:#fff;font-size:15px;font-weight:600;padding:12px 28px;
  border-radius:24px;text-decoration:none;box-shadow:0 6px 18px rgba(138,90,50,.3);
  transition:.25s;margin-top:4px;white-space:nowrap}
.ce-wx-btn:hover{transform:translateY(-2px);box-shadow:0 8px 22px rgba(138,90,50,.38)}

/* 聊天嵌入页：隐藏页脚 + 压缩顶部条，给对话区更多垂直空间（~110px） */
footer{display:none}
.ce-bar .inner{height:44px;padding:0 20px}  /* 56→44 */
.ce-bar .brand img{height:26px}
.ce-back{padding:4px 12px;font-size:12px}  /* 6/14/13 → 4/12/12 */
.ce-head{padding:6px 20px 4px}  /* 8+6 → 6+4 */
.ce-badge{width:32px;height:32px;font-size:17px;box-shadow:0 4px 10px rgba(138,90,50,.18)}  /* 38→32 */
.ce-meta .name{font-size:17px}  /* 19→17 */
.ce-meta .step{font-size:11px}  /* 12→11 */

@media(hover:hover){
  /* 透明触发条：固定在最顶部 44px。聊天加载后生效——鼠标进入触发条区域→顶部条滑出，离开（任何方向）→滑回隐藏 */
  .ce-trigger{
    position:fixed;top:0;left:0;right:0;height:44px;z-index:20;
    background:transparent;pointer-events:none;
  }
  .chat-loaded .ce-trigger{pointer-events:auto}
  .chat-loaded .ce-bar{
    position:fixed;top:0;left:0;right:0;z-index:50;
    transform:translateY(-100%);opacity:0;pointer-events:none;
    transition:transform .35s ease, opacity .35s ease;
  }
  .chat-loaded .ce-trigger:hover ~ .ce-bar,
  .chat-loaded .ce-bar:hover{
    transform:translateY(0);opacity:1;pointer-events:auto;
  }
}

@media(max-width:880px){
  .ce-meta .name{font-size:16px}
  .ce-meta .step{font-size:10.5px}
  .ce-head .inner{gap:8px}
  .ce-badge{width:30px;height:30px;font-size:16px}
}

















