  }
  .header .subtitle {
    font-size: 14px; color: #8a7560; letter-spacing: 5px;
  }

  .section-title {
    font-size: 20px; font-weight: 700; letter-spacing: 3px;
    margin: 22px 0 10px 0; display: flex; align-items: center; gap: 10px;
    color: #2b1d10;
    font-family: "Songti SC", "STSong", "Noto Serif CJK SC", serif;
  }
  .section-title::before {
    content: ''; width: 4px; height: 20px; background: #a07a52; border-radius: 2px;
  }

  /* === 科技感深蓝表格 === */
  .table-wrapper {
    background: linear-gradient(135deg, #0f1b4d 0%, #1d4ed8 50%, #3b82f6 100%);
    border-radius: 16px; overflow: hidden;
    box-shadow: 0 8px 40px rgba(15,27,77,0.25), 0 0 0 1px rgba(96,165,250,0.25);
    position: relative;
  }
  .table-wrapper::before {
    content: ''; position: absolute; inset: 0;
    background: radial-gradient(ellipse at top right, rgba(96,165,250,0.25), transparent 60%);
    pointer-events: none;
  }

  table { width: 100%; border-collapse: collapse; font-size: 14px; position: relative; z-index: 1; }
  thead th {
    background: rgba(15, 27, 77, 0.55); padding: 13px 10px; text-align: center;
    font-weight: 700; font-size: 13px; letter-spacing: 1.5px; color: #dbeafe;
    border-bottom: 1px solid rgba(96, 165, 250, 0.4); white-space: nowrap;
    text-shadow: 0 0 12px rgba(96,165,250,0.4);
  }
  tbody td {
    padding: 11px 10px; text-align: center; border-bottom: 1px solid rgba(255,255,255,0.06);
    color: rgba(255,255,255,0.94); line-height: 1.5; vertical-align: middle;
  }
  tbody tr:hover { background: rgba(96, 165, 250, 0.08); }
  tbody tr:last-child td { border-bottom: none; }

  .row-ai {
    background: linear-gradient(90deg, rgba(96,165,250,0.18), rgba(59,130,246,0.28), rgba(96,165,250,0.18)) !important;
  }
  .row-ai td { color: #fff !important; font-weight: 600; text-shadow: 0 0 10px rgba(147,197,253,0.6); }
  @keyframes pulse-glow {
    0%, 100% { box-shadow: inset 0 0 20px rgba(96,165,250,0.1); }
    50% { box-shadow: inset 0 0 30px rgba(96,165,250,0.3); }
  }
  .row-ai { animation: pulse-glow 3s ease-in-out infinite; }

  .level-cell { font-weight: 700; font-size: 14px; }
  .l0-cell { color: #cbd5e1; } .l1-cell { color: #86efac; } .l2-cell { color: #93c5fd; }
  .l3-cell { color: #c4b5fd; } .l4-cell { color: #fef08a; } .l5-cell { color: #fed7aa; }
  .l6-cell { color: #fca5a5; }

  .evo-table thead th:nth-child(1){width:10%}.evo-table thead th:nth-child(2){width:10%}
  .evo-table thead th:nth-child(3){width:14%}.evo-table thead th:nth-child(4){width:18%}
  .evo-table thead th:nth-child(5){width:16%}.evo-table thead th:nth-child(6){width:16%}
  .evo-table thead th:nth-child(7){width:16%}

  .path-table thead th:nth-child(1){width:10%}.path-table thead th:nth-child(2){width:14%}
  .path-table thead th:nth-child(3){width:16%}.path-table thead th:nth-child(4){width:18%}
  .path-table thead th:nth-child(5){width:16%}.path-table thead th:nth-child(6){width:26%}

  .arrow-divider { text-align:center; color:#a07a52; font-size:22px; margin:14px 0; letter-spacing:8px; opacity:0.7; }

  /* === 底部：三模块公式 + 四模块金句 === */
  .bottom-section {
    display: flex;
    flex-direction: column;
    gap: 18px;
    margin-top: 20px;
  }

  /* === 公式：3个组件 + 等号 + 整体说明 === */
  .formula-row {
    display: grid;
    grid-template-columns: 1.15fr 36px 1.15fr 36px 1.15fr 36px 1.15fr;
    gap: 12px;
    align-items: center;
    background: #fffaf0;
    border: 1px solid #e8d9be;
    border-radius: 16px;
    padding: 22px 28px;
    box-shadow: 0 4px 16px rgba(160,122,82,0.08);
  }

.formula-chip {
    background: linear-gradient(135deg, #f9efe0 0%, #f3e3c7 100%);
    border: 1px solid #d9bf94;
    border-radius: 12px;
    padding: 18px 18px;
    text-align: center;
    position: relative;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.6);
  }
  .formula-chip .chip-title {
    font-size: 19px; font-weight: 800; color: #5a3a1a; letter-spacing: 2px; margin-bottom: 6px;
  }
  .formula-chip .chip-desc {
    font-size: 12px; color: #8a6b48; letter-spacing: 1px; line-height: 1.6;
  }
  .formula-chip.positive { border-color: #86b088; }
  .formula-chip.positive .chip-title { color: #3b6640; }
  .formula-chip.positive .chip-desc { color: #6b8a6b; }
  .formula-chip.negative { border-color: #c0907a; }
  .formula-chip.negative .chip-title { color: #8b3a2a; }
  .formula-chip.negative .chip-desc { color: #a06b58; }

  .formula-result {
    background: linear-gradient(135deg, #5a3a1a 0%, #a07a52 100%);
    border: none;
    border-radius: 12px;
    padding: 18px 18px;
    text-align: center;
    box-shadow: 0 2px 8px rgba(160,122,82,0.25);
  }
  .formula-result .chip-title {
    font-size: 21px; font-weight: 800; color: #fff; letter-spacing: 2px;
  }
  .formula-result .chip-desc {
    font-size: 12px; color: rgba(255,255,255,0.75); letter-spacing: 1px; margin-top: 4px;
  }

  .formula-op {
    text-align: center;
    font-size: 30px;
    font-weight: 900;
    color: #a07a52;
  }

  /* === 金句：4个时代边界 === */
  .law-row {
    background: #fffaf0;
    border: 1px solid #e8d9be;
    border-radius: 16px;
    padding: 20px 24px;
    box-shadow: 0 4px 16px rgba(160,122,82,0.08);
  }
  .law-head {
    text-align: center;
    font-size: 14px;
    color: #8a7560;
    letter-spacing: 3px;
    margin-bottom: 14px;
    font-weight: 600;
  }
  .law-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 10px;
    margin-bottom: 14px;
  }
  .law-chip {
    background: linear-gradient(135deg, #f9efe0 0%, #f3e3c7 100%);
    border: 1px solid #d9bf94;
    border-radius: 10px;
    padding: 14px 12px;
    text-align: center;
    position: relative;
  }
  .law-chip .law-idx {
    font-size: 11px;
    color: #a07a52;
    letter-spacing: 2px;
    margin-bottom: 4px;
    font-weight: 700;
  }
  .law-chip .law-title {
    font-size: 17px;
    font-weight: 800;
    color: #5a3a1a;
    letter-spacing: 2px;
  }
  .law-chip .law-arrow {
    position: absolute;
    right: -10px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 16px;
    color: #a07a52;
    z-index: 1;
  }
  .law-chip:last-child .law-arrow { display: none; }
  .law-tagline {
    text-align: center;
    font-size: 17px;
    font-weight: 800;
    color: #2b1d10;
    letter-spacing: 2px;
    padding-top: 12px;
    border-top: 1px dashed #e8d9be;
  }
  .law-tagline .bolt { color: #d97706; margin-right: 6px; }

  @media (max-width: 1400px) {
    body { padding: 20px 24px; }
    .header h1 { font-size: 38px; }
    .header .eyebrow { font-size: 11px; letter-spacing: 4px; }
    table { font-size: 12px; } thead th { padding: 9px 6px; font-size: 11px; }
    tbody td { padding: 7px 6px; font-size: 12px; }
    .section-title { font-size: 17px; }
    .formula-chip .chip-title { font-size: 15px; }
    .formula-chip .chip-desc { font-size: 10px; }
    .formula-result .chip-title { font-size: 17px; }
    .formula-result .chip-desc { font-size: 10px; }
    .formula-op { font-size: 22px; }
    .law-chip .law-title { font-size: 15px; }
    .law-tagline { font-size: 14px; }
  }









